<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$id=(int)($_GET['id']??$_POST['invoice_id']??0);$q=$db->prepare('SELECT * FROM invoices WHERE id=?');$q->execute([$id]);$i=$q->fetch();if(!$i){http_response_code(404);exit('Invoice not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){$amount=min((float)$_POST['amount'],(float)$i['balance_due']);if($amount<=0)exit('Invalid payment amount.');$ref=trim((string)($_POST['reference']??''))?:'MAN-'.date('YmdHis').'-'.bin2hex(random_bytes(3));$method=trim((string)($_POST['method']??'manual'));$db->beginTransaction();try{$s=$db->prepare('INSERT INTO invoice_payments(invoice_id,lead_id,reference,gateway,amount,currency,status,paid_at,metadata) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$id,$i['lead_id']?:null,$ref,$method,$amount,$i['currency'],'successful',date('Y-m-d H:i:s'),json_encode(['source'=>'admin'],JSON_THROW_ON_ERROR)]);$paid=(float)$i['amount_paid']+$amount;$balance=max(0,(float)$i['total']-$paid);$status=$balance<=0.00001?'paid':'partially_paid';$u=$db->prepare('UPDATE invoices SET amount_paid=?,balance_due=?,status=? WHERE id=?');$u->execute([$paid,$balance,$status,$id]);$db->prepare('INSERT INTO invoice_events(invoice_id,event_type,description) VALUES(?,?,?)')->execute([$id,'payment_recorded','Manual payment of '.$i['currency'].' '.number_format($amount,2).' recorded.']);$db->commit();header('Location: invoice-view.php?token='.urlencode((string)$i['public_token']).'&payment=recorded');exit;}catch(Throwable $e){$db->rollBack();http_response_code(500);exit('Unable to record payment.');}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Record Payment</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card mx-auto" style="max-width:650px"><div class="card-body"><h1 class="h4">Record Payment</h1><p>Invoice <strong><?=htmlspecialchars($i['invoice_number'])?></strong> · Balance <?=htmlspecialchars($i['currency'])?> <?=number_format((float)$i['balance_due'],2)?></p><form method="post"><input type="hidden" name="invoice_id" value="<?=$id?>"><label class="form-label">Amount</label><input class="form-control mb-3" type="number" step="0.01" min="0.01" max="<?=htmlspecialchars((string)$i['balance_due'])?>" name="amount" required><label class="form-label">Method</label><select class="form-select mb-3" name="method"><option>bank_transfer</option><option>cash</option><option>card</option><option>paystack</option><option>flutterwave</option><option>other</option></select><label class="form-label">Reference</label><input class="form-control mb-3" name="reference"><button class="btn btn-dark">Record Payment</button></form></div></div></main></body></html>